  async checkAuth() {
    const data = await this.apiRequest('/api/auth/me');
    if (data.success && data.authenticated) {
      this.user = data.user;
      this.accessibleAcademies = data.accessibleAcademies || [];

      if (data.user && data.user.effectiveTheme) {
        this.colorTheme = data.user.effectiveTheme;
        localStorage.setItem('colorTheme', this.colorTheme);
        this.applyColorTheme(this.colorTheme);
      }

      if (this.tenantAcademy && this.tenantAcademy.id) {
        this.selectedAcademyId = this.tenantAcademy.id;
        localStorage.setItem('selectedAcademyId', this.selectedAcademyId);
      } else if (this.accessibleAcademies && this.accessibleAcademies.length > 0) {
        const matching = this.accessibleAcademies.find(a => a.id == this.selectedAcademyId);
        if (matching) {
          this.selectedAcademyId = matching.id;
        } else {
          this.selectedAcademyId = this.accessibleAcademies[0].id;
        }
        localStorage.setItem('selectedAcademyId', this.selectedAcademyId);
        const activeAc = matching || this.accessibleAcademies[0];
        if (!this.user.academyName && activeAc) {
          this.user.academyName = activeAc.name;
        }
        if (!this.user.academyLogo && activeAc) {
          this.user.academyLogo = activeAc.logo_url;
        }
        if (!this.tenantAcademy && activeAc) {
          this.tenantAcademy = activeAc;
        }
      }

      this.showApp();
    } else {
      this.logout();
    }
  },

  async handleLogin() {
    const email = document.getElementById('login-email').value.trim();
    const password = document.getElementById('login-password').value.trim();
    const submitBtn = document.getElementById('btn-login-submit');

    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Signing In...';

    const res = await this.apiRequest('/api/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });

    submitBtn.disabled = false;
    submitBtn.innerText = 'Sign In to Portal';

    if (res.success) {
      this.token = res.token;
      this.user = res.user;
      localStorage.setItem('token', res.token);

      if (res.user.academyId) {
        this.selectedAcademyId = res.user.academyId;
        localStorage.setItem('selectedAcademyId', res.user.academyId);
      }

      this.showToast('Logged in successfully', 'success');
      await this.checkAuth();
    } else {
      if (res.error && res.error.includes('academy not found')) {
        this.showToast('Login failed: Account or academy not found. If this is a fresh deployment, click "Initialize / Seed Database" below.', 'warning');
      } else {
        this.showToast(res.error || 'Login failed', 'danger');
      }
    }
  },

