  onStudentBranchChange(branchId) {
    const batchSelect = document.getElementById('stu-batch');
    if (!batchSelect) return;
    const allBatches = window._cachedBatchesForStudentForm || [];
    const filtered = branchId ? allBatches.filter(b => Number(b.branch_id) === Number(branchId)) : allBatches;
    batchSelect.innerHTML = `
      <option value="">-- Choose Batch --</option>
      ${filtered.map(b => `<option value="${b.id}">${b.name} (${b.sport_name})</option>`).join('')}
    `;
  },

  async submitAddStudent() {
    const first_name = document.getElementById('stu-fn').value.trim();
    const last_name = document.getElementById('stu-ln').value.trim();
    const email = document.getElementById('stu-email').value.trim();
    const phone = document.getElementById('stu-phone').value.trim();
    const guardian_name = document.getElementById('stu-guardian').value.trim();
    const date_of_birth = this.normalizeDateToIso(document.getElementById('stu-dob').value);
    const branch_id = document.getElementById('stu-branch') ? document.getElementById('stu-branch').value : null;
    const batch_id = document.getElementById('stu-batch') ? document.getElementById('stu-batch').value : null;

    if (!first_name || !last_name) {
      this.showToast('First and last name are required', 'danger');
      return;
    }

    const res = await this.apiRequest('/api/academy/students', {
      method: 'POST',
      body: JSON.stringify({
        first_name,
        last_name,
        email,
        phone,
        guardian_name,
        date_of_birth,
        branch_id: branch_id || null,
        batch_id: batch_id || null,
      }),
    });

    if (res.success) {
      this.showToast(`Enrolled: ${first_name} ${last_name} (${res.studentCode})`, 'success');
      this.closeModal();
      this.renderStudents();
    } else {
      this.showToast(res.error || 'Failed to enroll student', 'danger');
    }
  },

  exportStudentsExcel() {
    if (!this.currentStudentsData || !this.currentStudentsData.length) {
      this.showToast('No students to export', 'info');
      return;
    }

    const exportRows = this.currentStudentsData.map(s => ({
      'Student Code': s.student_code,
      'First Name': s.first_name,
      'Last Name': s.last_name,
      'Email': s.email || '',
      'Phone': s.phone || '',
      'Guardian Name': s.guardian_name || '',
      'Guardian Phone': s.guardian_phone || '',
      'Branch': s.branch_name || 'Main Campus',
      'Enrolled Batches': s.enrolled_batches || '',
      'Status': s.status,
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportRows);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Students');
    XLSX.writeFile(workbook, `Students_${new Date().toISOString().split('T')[0]}.xlsx`);
    this.showToast('Excel report generated via SheetJS', 'success');
  },

  exportStudentsCsv() {
    if (!this.currentStudentsData || !this.currentStudentsData.length) {
      this.showToast('No students to export', 'info');
      return;
    }
    const headers = ['Student Code', 'First Name', 'Last Name', 'Email', 'Phone', 'Guardian Name', 'Guardian Phone', 'Branch', 'Enrolled Batches', 'Status'];
    const rows = this.currentStudentsData.map(s => [
      `"${(s.student_code || '').replace(/"/g, '""')}"`,
      `"${(s.first_name || '').replace(/"/g, '""')}"`,
      `"${(s.last_name || '').replace(/"/g, '""')}"`,
      `"${(s.email || '').replace(/"/g, '""')}"`,
      `"${(s.phone || '').replace(/"/g, '""')}"`,
      `"${(s.guardian_name || '').replace(/"/g, '""')}"`,
      `"${(s.guardian_phone || '').replace(/"/g, '""')}"`,
      `"${(s.branch_name || 'Main Campus').replace(/"/g, '""')}"`,
      `"${(s.enrolled_batches || '').replace(/"/g, '""')}"`,
      `"${(s.status || 'active').replace(/"/g, '""')}"`,
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Students_${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    this.showToast('Exported students CSV successfully', 'success');
  },

  async downloadStudentSampleCsv() {
    let branchId = '';
    let batchId = '';
    try {
      const brRes = await this.apiRequest('/api/academy/branches');
      if (brRes.branches && brRes.branches.length > 0) branchId = brRes.branches[0].id;
      const btRes = await this.apiRequest('/api/academy/batches');
      if (btRes.batches && btRes.batches.length > 0) batchId = btRes.batches[0].id;
    } catch (e) {}

    const csvContent = 'first_name,last_name,email,phone,date_of_birth,gender,emergency_contact,branch_id,batch_id\n' +
      `Aarav,Patel,aarav.patel@example.com,9876543210,2010-05-15,male,9876543211,${branchId},${batchId}\n` +
      `Diya,Shah,diya.shah@example.com,9876543212,2012-08-20,female,9876543213,${branchId},${batchId}\n` +
      `Kabir,Mehta,kabir.mehta@example.com,9876543214,2011-11-05,male,9876543215,,\n`;
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'students_import_template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    this.showToast('Sample CSV template downloaded', 'success');
  },

